customCSS:
.t, .history { color: #808080; }
.join { color: #afd700; }
.part, .quit { color: #808080; }
.kick, .error { color: #d75f5f; }
.notice { color: #d7af5f; }
.action { color: #d787af; }
.mode, .nick, .topic, .server { color: #00afaf; }
.highlight { color: #d0d0d0; background-color: #8787af; border-left: 3px solid #d787af; padding-left: 8px; }
.reply { color: #808080; border-left: 2px solid #5fafd7; padding-left: 6px; }
.oper { color: #1c1c1c; background-color: #d7af5f; }
.reactions { color: #5fafd7; background-color: #303030; }
.card { background-color: #303030; border-color: #808080; }
.card-title { color: #5fafd7; }
.card-desc { color: #808080; }
.daychange { color: #808080; border-color: #303030; }
